import * as core from './returning-orders-core.mjs';
import {returnIds,returningCase} from './returning-orders-content.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const fill=(source,key,values={})=>esc(source.text[key].replace(/\{(tens|ones|table|returned|target|left|remaining|answer)\}/g,(_,k)=>Object.hasOwn(values,k)?String(values[k]):`{${k}}`));
const signature=(tens,ones,total)=>integer(tens)&&integer(ones)&&tens>=1&&ones>=0&&ones<10&&10*tens+ones===total?`bundle:0:${tens}:${ones}`:null;
const integer=Number.isInteger;
const sourceReadout=s=>/four tens and two ones make 42 counters/i.test(s.text.sourceLine);
const tableReadout=s=>/wrapped tens \{tens\}; loose counters \{ones\}; all counters \{table\}/i.test(s.text.tableLine);
const storeReadout=s=>/wrapped tens \{tens\}; loose counters \{ones\}; all counters \{returned\}/i.test(s.text.storeLine);
const caseReadout=s=>new RegExp(`one ten and ${s.returnedOnes===2?'two':'seven'} ones`,'i').test(s.text.caseLabel);
const exampleReadout=s=>/return 16: one ten and six ones/i.test(s.text.exampleBody);
const marks=n=>Array.from({length:n},()=>'<span class="return-mark" data-return-mark aria-hidden="true"></span>').join('');
const tens=n=>Array.from({length:n},()=>`<span class="return-ten" data-return-ten aria-label="Wrapped group of ten">${marks(10)}</span>`).join('');
function tray(name,wrapped,loose,kind){const frame=Math.min(loose,10),overflow=loose-frame,label=kind==='store'?'store tray':'table frame';return `<section class="return-tray return-tray-${kind}" aria-label="${esc(name)}"><h3>${esc(name)}</h3><div class="return-ten-row">${tens(wrapped)}</div><div class="return-loose"><div class="return-frame" aria-label="${frame} loose counters in the ${label}">${marks(frame)}</div>${overflow?`<div class="return-overflow" aria-label="${overflow} extra loose counters">${marks(overflow)}</div>`:''}</div></section>`;}
function picture(w){const m=w.model,s=w.source,t=core.tableTotal(m),r=core.returnedTotal(m);return `<section class="return-model" id="return-model" tabindex="-1"><h2>Move the pretend counters</h2><p>${fill(s,'sourceLine')}</p><p class="tiny">${fill(s,'modelTip')}</p><div class="return-trays">${tray(s.text.tableName,m.tableTens,m.tableOnes,'table')}${tray(s.text.storeName,m.returnedTens,m.returnedOnes,'store')}</div><p class="return-count" data-return-table-line>${fill(s,'tableLine',{tens:m.tableTens,ones:m.tableOnes,table:t})}</p><p class="return-count" data-return-store-line>${fill(s,'storeLine',{tens:m.returnedTens,ones:m.returnedOnes,returned:r})}</p><p>${fill(s,'targetLine',{target:s.target})} ${core.returningComplete(s,m)?fill(s,'doneLine',{target:s.target,remaining:t}):fill(s,'needLine',{left:s.target-r})}</p></section>`;}
function actions(w){const m=w.model,s=w.source;return `<section class="return-actions" aria-label="Change the picture">${button(s.text.openTen,`data-return-action="open" ${m.openTen||!m.tableTens?'disabled':''}`)}${button(s.text.makeTen,`data-return-action="make" ${!m.openTen||m.tableOnes<10?'disabled':''}`)}${button(s.text.returnTen,`data-return-action="return-ten" ${!m.tableTens||m.returnedTens>=1?'disabled':''}`)}${button(s.text.returnOne,`data-return-action="return-one" ${!m.tableOnes||m.returnedOnes>=s.returnedOnes?'disabled':''}`)}${button(s.text.bringTen,`data-return-action="bring-ten" ${!m.returnedTens?'disabled':''}`)}${button(s.text.bringOne,`data-return-action="bring-one" ${!m.returnedOnes?'disabled':''}`)}${button(s.text.resetModel,'data-return-action="reset"')}</section>`;}
function checkSummary(h,current=false,earlier=false,currentModel=null){
 const s=h.source,m=h.model,values={target:s.target,answer:s.start-s.target},past=earlier||!current;
 const arrangement=past?`<p class="tiny">Earlier arrangement at this check: table ${core.tableTotal(m)}, store tray ${core.returnedTotal(m)}.${currentModel?` Current picture above: table ${core.tableTotal(currentModel)}, store tray ${core.returnedTotal(currentModel)}.`:''}</p>`:'';
 return `<section class="return-check-summary"><p>${current?'Current number check':'Earlier number check'}: ${esc(h.raw)}. ${fill(s,h.numberMatches?'match':'different',values)}</p>${arrangement}<p>${past?'<strong>At this earlier check:</strong> ':''}${fill(s,h.picturedComplete?'modelFinished':'modelIncomplete')}</p>${h.priorHistoryUnknown?'<p class="tiny">Earlier encounters before recovery are unknown.</p>':''}</section>`;
}
function response(w){const s=w.source,h=w.currentFeedback===null?null:w.checks[w.currentFeedback],earlier=h&&['tableTens','tableOnes','returnedTens','returnedOnes','openTen'].some(k=>h.model[k]!==w.model[k]);return `<section class="return-response"><h2>What remains?</h2><p class="return-equation">${s.start} − ${s.target} = ?</p><form data-return-form><label for="return-number">${fill(s,'entryLabel')}</label><input id="return-number" data-return-raw type="text" inputmode="numeric" maxlength="24" autocomplete="off" spellcheck="false" value="${esc(w.raw)}" ${w.error?'aria-invalid="true"':''}><p class="tiny">Write a whole number from 0 to 99. Your number does not move the counters.</p>${w.error?`<p id="return-syntax" role="alert" tabindex="-1">${fill(s,'syntax')}</p>`:''}<div class="return-form-actions"><button type="submit" class="primary" data-return-check>${fill(s,'check')}</button>${button(s.text.keep,'data-return-keep')}</div></form>${w.checks.length===8?'<p class="tiny" data-return-cap>The next valid number check will replace the oldest local check for this case.</p>':''}${h?`<div id="return-feedback" role="status" tabindex="-1">${checkSummary(h,true,earlier,earlier?w.model:null)}</div>`:''}<p id="return-kept-confirmation" role="status" tabindex="-1">${w.kept?'A copy of this draft is kept, including its picture and typed number.':''}</p><details class="return-history"><summary>Earlier checks and kept copy (${w.checks.length} checks)</summary>${w.checks.map(x=>checkSummary(x)).join('')}${w.kept?`<section><h3>Kept draft</h3><p>${fill(w.kept.source,'prompt')}</p><p>Typed number: ${esc(w.kept.raw||'(blank)')}. Earlier picture: table ${core.tableTotal(w.kept.model)}, store tray ${core.returnedTotal(w.kept.model)}.</p>${w.kept.latestCheck?checkSummary(w.kept.latestCheck):'<p>No number check in this kept copy.</p>'}</section>`:''}</details></section>`;}
function chooser(root,selected){const expanded=!!root&&Object.keys(root.cases).length>0;const choices=returnIds.map(id=>{const s=root?.cases[id]?.source||returningCase(id),active=selected===id;return button(expanded?s.text.caseLabel:`Return ${s.target}`,`data-return-choose="${id}" aria-pressed="${active}"`)}).join('');const current=root?.cases[selected]?.source||returningCase(selected);return `<section class="return-chooser" data-return-root><a href="#numbers">Back to Number Garden</a><h1>Returning seed counters</h1><p>Choose a return. Both are open to try.</p><div class="return-choices">${choices}</div>${selected?`<section class="return-preview"><h2>Return ${current.target}</h2><p>${!expanded?`42 − ${current.target} = ?`:fill(current,'prompt')}</p>${button(current.text.start,`data-return-start="${selected}"`,true)}<p id="return-start-status" role="status"></p></section>`:''}${root?.active?'<a class="secondary" href="#numbers/return">Back to the working table</a>':''}</section>`;}
export function returningOrdersEntry(){return '<section class="return-entry"><h2>Bundle Burrow: Returning Supply Orders</h2><p>Start with 42 pretend seed counters. Open a ten when useful, then move the returned counters into a separate tray.</p><a class="secondary" href="#numbers/return">Try returning seed counters</a></section>';}
export function renderReturning(state,detail=''){
 const v=core.returningView(state);
 if(v.unavailable)return {html:`<section class="returning-orders" data-return-root><a href="#numbers">Back to Number Garden</a><h1>Returning seed counters</h1><p>This saved return uses a format this version cannot play. Its original work is retained unchanged in your notes.</p><p><a href="#notes">Visit grown-up notes and download a copy</a> · <a href="#map">Visit the learning map</a></p><details><summary>Start a fresh returning table</summary><p>The original saved record will be kept inside the new notes. Check your download first if you want another copy.</p>${button('Confirm fresh start and keep the old record','data-return-recover',true)}</details><p id="return-recovery-status" role="status"></p></section>`,examples:[]};
 const root=v.root,selected=returnIds.includes(detail)?detail:(root?.active||returnIds[0]);
 if(!root||detail==='choose'||returnIds.includes(detail)){
  const examples=root&&Object.keys(root.cases).length?returnIds.map(id=>{const s=root.cases[id]?.source||returningCase(id);return caseReadout(s)?signature(s.returnedTens,s.returnedOnes,s.target):null;}).filter(Boolean):[];
  return {html:`<div class="returning-orders">${chooser(root,selected)}</div>`,examples};
 }
 const w=v.work;if(!w)return {html:`<div class="returning-orders">${chooser(root,selected)}</div>`,examples:[]};
 const s=w.source,m=w.model,examples=[...new Set([sourceReadout(s)?signature(4,2,42):null,tableReadout(s)?signature(m.tableTens,m.tableOnes,core.tableTotal(m)):null,storeReadout(s)?signature(m.returnedTens,m.returnedOnes,core.returnedTotal(m)):null].filter(Boolean))];
 return {html:`<div class="returning-orders" data-return-root><a href="#numbers">Back to Number Garden</a><header><h1>${fill(s,'title')}</h1><p>${fill(s,'intro')}</p><p>${fill(s,'caseLabel')}</p><p>${fill(s,'prompt')}</p>${hearButton(s.text.prompt,s.text.hear)}</header><p><a href="#numbers/return/ledger">Write what this returning picture means</a></p>${picture(w)}${actions(w)}${response(w)}<details class="return-help" data-return-help><summary>${fill(s,'helpTitle')}</summary><p>${fill(s,'helpBody')}</p><details data-return-example><summary>${fill(s,'exampleTitle')}</summary><p>${fill(s,'exampleBody')}</p></details><p>${fill(s,'talk')}</p>${button(s.text.together,'data-return-together')}<p id="return-together-status" role="status"></p></details><p><a class="secondary" href="#numbers/return/choose">${fill(s,'newCase')}</a> <a class="secondary" href="#numbers/compare">Compare the same two numbers</a></p></div>`,examples};
}
export function returningOrdersNotes(state){
 if(!Object.hasOwn(state,'returningOrders'))return '';
 const v=core.returningView(state);
 if(v.unavailable)return `<section class="panel"><h2>Returning Supply Orders</h2><p>Unsupported saved work retained unchanged. Download the notes before an explicit fresh start.</p><pre>${esc(JSON.stringify(state.returningOrders,null,2))}</pre></section>`;
 return `<details class="panel"><summary>Returning Supply Orders: pictured returns and entered remainders</summary><p>These are local records of supplied quantities, picture moves and entered numbers. They do not establish independent subtraction or mastery.</p>${Object.hasOwn(v.root,'retainedRaw')?'<p>Earlier encounters before recovery are unknown.</p>':''}${Object.values(v.root.cases).map(w=>`<section><h3>${fill(w.source,'caseLabel')}</h3><p>Picture: ${core.returningComplete(w.source,w.model)?'return complete':'return in progress'}; table ${core.tableTotal(w.model)}, store tray ${core.returnedTotal(w.model)}. Typed number: ${esc(w.raw||'(blank)')}. ${w.checks.length} local checks. ${w.kept?'One draft kept.':'No kept draft.'}</p><details><summary>Exact frozen source, checks and kept copy</summary><pre>${esc(JSON.stringify(w,null,2))}</pre></details></section>`).join('')}${Object.hasOwn(v.root,'retainedRaw')?`<details><summary>Original recovered record</summary><pre>${esc(JSON.stringify(v.root.retainedRaw,null,2))}</pre></details>`:''}<a href="#numbers/return">Visit Returning Supply Orders</a></details>`;
}
export function bindReturning(state,{save,render,navigate,focus,noteDisplay,canExport}={}){
 const scope=document.querySelector('.returning-orders');if(!scope)return;
 const target=s=>focus?.(s)||document.querySelector(s)?.focus();
 const rerender=(ok,where)=>{if(!ok)return;save?.();render?.();if(where)target(where);};
 scope.querySelectorAll('[data-return-choose]').forEach(b=>b.onclick=()=>navigate?.(`#numbers/return/${b.dataset.returnChoose}`));
 scope.querySelector('[data-return-start]')?.addEventListener('click',e=>{if(!core.startReturning(state,e.currentTarget.dataset.returnStart)){const p=scope.querySelector('#return-start-status');if(p)p.textContent='This new source or notebook is too large to start safely. Your earlier work is unchanged. Download your notes before trying again.';return;}save?.();navigate?.('#numbers/return');});
 scope.querySelectorAll('[data-return-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.returnAction;if(!core.moveReturning(state,a))return;save?.();render?.();const old=document.querySelector(`[data-return-action="${a}"]`);target(old&&!old.disabled?`[data-return-action="${a}"]`:'#return-model');});
 scope.querySelector('[data-return-raw]')?.addEventListener('input',e=>{if(core.setReturningRaw(state,e.target.value)){save?.();scope.querySelector('#return-feedback')?.remove();scope.querySelector('#return-syntax')?.remove();e.target.removeAttribute('aria-invalid');}});
 scope.querySelector('[data-return-form]')?.addEventListener('submit',e=>{e.preventDefault();if(!core.checkReturning(state))return;save?.();render?.();target(core.returningView(state).work.error?'#return-syntax':'#return-feedback');});
 scope.querySelector('[data-return-keep]')?.addEventListener('click',()=>rerender(core.keepReturning(state),'#return-kept-confirmation'));
 scope.querySelector('[data-return-recover]')?.addEventListener('click',()=>{if(!window.confirm('Start a fresh returning table while keeping the entire old record in your notes?'))return;if(core.recoverReturning(state,canExport)){save?.();render?.();target('[data-return-root] h1');}else{const p=scope.querySelector('#return-recovery-status');if(p){p.textContent='This recovery would make the notes download too large or complex to import. The earlier record is unchanged. Download your notes, then start a separate explorer.';p.tabIndex=-1;p.focus();}}});
 scope.querySelector('[data-return-help]')?.addEventListener('toggle',e=>{if(e.currentTarget.open&&core.useReturningSupport(state,'help'))save?.();});
 scope.querySelector('[data-return-example]')?.addEventListener('toggle',e=>{if(e.currentTarget.open){core.useReturningSupport(state,'example');const s=core.returningView(state).work?.source;if(s&&exampleReadout(s))noteDisplay?.(['bundle:0:1:6']);save?.();}});
 scope.querySelector('[data-return-together]')?.addEventListener('click',()=>{if(core.useReturningSupport(state,'together'))save?.();const p=scope.querySelector('#return-together-status');if(p)p.textContent='Talk through the picture together. Nothing moved or answered automatically.';});
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(core.useReturningSupport(state,'narrationRequested'))save?.();},{capture:true}));
}
